def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    for b in op:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c

    # Always cooperate against a pure cooperator
    if opp_d == 0:
        return 'C'

    # Detect a very exploitative opponent: defect almost always
    if opp_d * 4 > n * 3:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Late game: try a few defections near the end if opponent is exploitable
    remaining = 100 - n
    if remaining <= 2:
        if opp_c * 2 > n:
            return 'D'
        return 'D'

    # Count consecutive opponent defections from the end
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            consec_d += 1
        else:
            break

    # Count consecutive opponent cooperations from the end
    consec_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            consec_c += 1
        else:
            break

    last_my = me[-1]
    last_op = op[-1]

    # Opponent just cooperated
    if last_op == 'C':
        # If we defected last, return to cooperation to rebuild trust
        if last_my == 'D':
            return 'C'
        # If opponent is very cooperative, keep cooperating, rare probe early
        if opp_d * 5 < n:
            if n < 60 and n % 23 == 0 and rng.random() < 0.2:
                return 'D'
            return 'C'
        # Moderate defect rate: cooperate to encourage them
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    # Opponent just defected
    if consec_d >= 3:
        # Sustained defection: mostly defect, occasional olive branch
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    if consec_d == 2:
        # Two in a row: punish but open a window for repair
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # Single defection by opponent
    # If we defected last too, break the DD cycle immediately with C
    if last_my == 'D':
        return 'C'
    # If opponent has been mostly cooperative recently, forgive quickly
    recent = op[-6:] if n >= 6 else op
    rc = 0
    for b in recent:
        if b == 'C':
            rc += 1
    if rc * 10 >= len(recent) * 7:
        return 'C'
    # Otherwise retaliate once, then plan to forgive
    if rng.random() < 0.75:
        return 'D'
    return 'C'
